  <button id="reset">Reset / Rack</button>
</main>

<script>
const canvas=document.getElementById("table"),ctx=canvas.getContext("2d");
const W=960,H=540,R=13;
canvas.width=W;canvas.height=H;
const felt={l:34,t:34,r:W-34,b:H-34};
const pockets=[
 [felt.l,felt.t],[W/2,felt.t],[felt.r,felt.t],
 [felt.l,felt.b],[W/2,felt.b],[felt.r,felt.b]
];
let balls=[],running=true,last=performance.now(),dragging=false,dragX=0,dragY=0;

function reset(input){
  balls=(input||[]).map(b=>({
    x:+b.x,y:+b.y,vx:+(b.vx||0),vy:+(b.vy||0),
    cue:!!b.cue,potted:false
  }));
  draw();
}

function shoot(vx,vy){
  const b=balls.find(b=>b.cue&&!b.potted);
  if(b){b.vx=+vx||0;b.vy=+vy||0}
}

function step(dt){
  dt=Math.max(0,Math.min(+dt||0,.25));
  const count=Math.max(1,Math.ceil(dt/.008));
  for(let i=0;i<count;i++) physics(dt/count);
  draw();
}

function physics(dt){
  const friction=Math.pow(.991,dt*60);

  for(const b of balls){
    if(b.potted)continue;
    b.x+=b.vx*dt;b.y+=b.vy*dt;
    b.vx*=friction;b.vy*=friction;
    if(Math.hypot(b.vx,b.vy)<2.5)b.vx=b.vy=0;

    for(const p of pockets){
      if(Math.hypot(b.x-p[0],b.y-p[1])<R*1.65){
        b.potted=true;b.vx=b.vy=0;break;
      }
    }
    if(b.potted)continue;

    if(b.x<felt.l+R){b.x=felt.l+R;if(b.vx<0)b.vx=-b.vx*.94}
    if(b.x>felt.r-R){b.x=felt.r-R;if(b.vx>0)b.vx=-b.vx*.94}
    if(b.y<felt.t+R){b.y=felt.t+R;if(b.vy<0)b.vy=-b.vy*.94}
    if(b.y>felt.b-R){b.y=felt.b-R;if(b.vy>0)b.vy=-b.vy*.94}
  }

  for(let i=0;i<balls.length;i++){
    const a=balls[i];if(a.potted)continue;
    for(let j=i+1;j<balls.length;j++){
      const b=balls[j];if(b.potted)continue;
      let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);
      if(d>=R*2)continue;
      if(!d){dx=1;dy=0;d=1}
      const nx=dx/d,ny=dy/d,overlap=R*2-d;
      a.x-=nx*overlap/2;a.y-=ny*overlap/2;
      b.x+=nx*overlap/2;b.y+=ny*overlap/2;
      const relx=b.vx-a.vx,rely=b.vy-a.vy;
      const along=relx*nx+rely*ny;
      if(along<0){
        a.vx+=along*nx;a.vy+=along*ny;
        b.vx-=along*nx;b.vy-=along*ny;
      }
    }
  }
}

function state(){
  return balls.map(b=>({
    x:b.x,y:b.y,vx:b.vx,vy:b.vy,potted:!!b.potted,cue:!!b.cue
  }));
}
function pause(){running=false}
function resume(){
  if(!running){running=true;last=performance.now();requestAnimationFrame(loop)}
}
window.sim={W,H,R,reset,step,state,shoot,pause,resume};

function rounded(x,y,w,h,r){
  ctx.beginPath();ctx.moveTo(x+r,y);
  ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);
  ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();
}

function draw(){
  ctx.clearRect(0,0,W,H);
  ctx.fillStyle="#17100b";ctx.fillRect(0,0,W,H);
  ctx.fillStyle="#5a3218";rounded(12,12,W-24,H-24,18);ctx.fill();
  ctx.fillStyle="#875225";rounded(23,23,W-46,H-46,12);ctx.fill();
  ctx.fillStyle="#17633d";rounded(felt.l,felt.t,felt.r-felt.l,felt.b-felt.t,5);ctx.fill();

  for(const p of pockets){
    ctx.beginPath();ctx.arc(p[0],p[1],22,0,Math.PI*2);
    ctx.fillStyle="#080909";ctx.fill();
  }

  if(dragging){
    const b=balls.find(b=>b.cue&&!b.potted);
    if(b){
      const dx=b.x-dragX,dy=b.y-dragY,len=Math.hypot(dx,dy);
      if(len>2){
        const ux=dx/len,uy=dy/len;
        ctx.save();ctx.setLineDash([10,8]);
        ctx.strokeStyle="#fff";ctx.lineWidth=2;
        ctx.beginPath();ctx.moveTo(b.x,b.y);
        ctx.lineTo(b.x+ux*Math.min(330,len*2.2),
                   b.y+uy*Math.min(330,len*2.2));ctx.stroke();ctx.restore();
      }
    }
  }

  balls.forEach((b,i)=>{
    if(b.potted)return;
    ctx.beginPath();ctx.arc(b.x+3,b.y+4,R+1,0,Math.PI*2);
    ctx.fillStyle="rgba(0,0,0,.28)";ctx.fill();
    ctx.beginPath();ctx.arc(b.x,b.y,R,0,Math.PI*2);
    ctx.fillStyle=b.cue?"#f7f5e8":
      ["#e5b42b","#245db7","#c83a31","#5c2b85","#e57c23","#198b56"][i%6];
    ctx.fill();ctx.strokeStyle="rgba(0,0,0,.55)";ctx.stroke();

    if(!b.cue){
      ctx.beginPath();ctx.arc(b.x,b.y,5,0,Math.PI*2);
      ctx.fillStyle="#f6f1dc";ctx.fill();
      ctx.fillStyle="#222";ctx.font="7px Arial";ctx.textAlign="center";
      ctx.textBaseline="middle";ctx.fillText(i,b.x,b.y);
    }
  });
}

function pointerPos(e){
  const r=canvas.getBoundingClientRect();
  return {x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height};
}
canvas.addEventListener("pointerdown",e=>{
  const p=pointerPos(e),b=balls.find(b=>b.cue&&!b.potted);
  if(b&&Math.hypot(p.x-b.x,p.y-b.y)<=R*1.6){
    dragging=true;dragX=p.x;dragY=p.y;
    canvas.setPointerCapture(e.pointerId);draw();
  }
});
canvas.addEventListener("pointermove",e=>{
  if(dragging){const p=pointerPos(e);dragX=p.x;dragY=p.y;draw()}
});
canvas.addEventListener("pointerup",e=>{
  if(!dragging)return;
  const p=pointerPos(e),b=balls.find(b=>b.cue&&!b.potted);
  dragging=false;
  if(b){
    const dx=b.x-p.x,dy=b.y-p.y,len=Math.hypot(dx,dy);
    if(len>5){
      const power=Math.min(1100,len*5.2);
      shoot(dx/len*power,dy/len*power);
    }
  }
  draw();
});

function defaultRack(){
  const a=[{x:220,y:H/2,vx:0,vy:0,cue:true}],x=700,cy=H/2,d=R*2.08;
  for(let row=0;row<5;row++)
    for(let k=0;k<=row;k++)
      a.push({x:x+row*d*.866,y:cy+(k-row/2)*d,vx:0,vy:0,cue:false});
  reset(a);
}
document.getElementById("reset").addEventListener("click",defaultRack);

function loop(t){
  if(!running)return;
  step(Math.min(.04,(t-last)/1000));last=t;
  requestAnimationFrame(loop);
}
defaultRack();
requestAnimationFrame(loop);
</script>
